import java.sql.*;
public class MultiResultSetProc {
    public static void main(String[] args) {
        try (Connection conn = DriverManager.getConnection("jdbc:mysql://localhost/db", "user", "pass");
             CallableStatement cstmt = conn.prepareCall("{call GetEmpAndDept()}")) {
            boolean isResultSet = cstmt.execute();
            int resultSetNumber = 1;
            while (isResultSet) {
                ResultSet rs = cstmt.getResultSet();
                System.out.println("ResultSet #" + resultSetNumber++);
                while (rs.next()) {
                    // process each row
                }
                rs.close();
                isResultSet = cstmt.getMoreResults(); // move to next
            }
        } catch (SQLException e) {
            e.printStackTrace();
        }
    }
}
```

