```java
import java.sql.*;
public class MultiResultSetExample {
    public static void main(String[] args) {
        String url = "jdbc:sqlserver://localhost:1433;databaseName=LibraryDB";
        try (Connection conn = DriverManager.getConnection(url, "user", "pass");
             CallableStatement cstmt = conn.prepareCall("{call GetOverdueAndPopularBooks()}")) {
            boolean isResultSet = cstmt.execute();
            int setNumber = 1;
            while (isResultSet) {
                try (ResultSet rs = cstmt.getResultSet()) {
                    System.out.println("=== Result Set " + setNumber++ + " ===");
                    ResultSetMetaData meta = rs.getMetaData();
                    int colCount = meta.getColumnCount();
                    while (rs.next()) {
                        for (int i = 1; i <= colCount; i++) {
                            System.out.print(rs.getString(i) + "\t");
                        }
                        System.out.println();
                    }
                }
                // Check for more result sets
                isResultSet = cstmt.getMoreResults();
                // Also check for update counts (if any) using getUpdateCount()
            }
        } catch (SQLException e) {
            e.printStackTrace();
        }
    }
}
```

T-SQL statements for user creation, role assignment, and permission granting in SQL Server with best practices:
```sql
-- 1. Create server login (use Windows Auth if possible, otherwise SQL login with strong policy)
CREATE LOGIN [CORP\JohnSmith] FROM WINDOWS WITH DEFAULT_DATABASE = UniversityDB;
-- Or SQL login:
CREATE LOGIN JaneDoe WITH PASSWORD = 'J@neDoe2024!', CHECK_EXPIRATION = ON, CHECK_POLICY = ON;

-- 2. Create database user
USE UniversityDB;
CREATE USER JohnSmith FOR LOGIN [CORP\JohnSmith];
CREATE USER JaneDoe FOR LOGIN JaneDoe;

-- 3. Create custom database role
CREATE ROLE DataAnalyst;

-- 4. Grant permissions to role
GRANT SELECT ON Student TO DataAnalyst;
GRANT SELECT ON Enrollment TO DataAnalyst;
GRANT SELECT ON Course TO DataAnalyst;
GRANT EXECUTE ON dbo.GetStudentGPA TO DataAnalyst;
DENY DELETE, INSERT, UPDATE ON Student TO DataAnalyst;  -- read-only

-- 5. Assign users to role
EXEC sp_addrolemember 'DataAnalyst', 'JohnSmith';
EXEC sp_addrolemember 'DataAnalyst', 'JaneDoe';

-- 6. Use schemas for fine-grained control
CREATE SCHEMA HR;
CREATE TABLE HR.Employee (...);
GRANT SELECT ON SCHEMA::HR TO DataAnalyst;

-- 7. Fixed database roles
EXEC sp_addrolemember 'db_datareader', 'JaneDoe';
EXEC sp_addrolemember 'db_datawriter', 'JohnSmith';

-- 8. Revoke or deny as needed
REVOKE SELECT ON Course TO DataAnalyst;
DENY SELECT ON HR.Salary TO DataAnalyst;  -- explicit deny overrides grant

-- 9. View permissions
EXEC sp_helprotect @username = 'JaneDoe';
```
